// ServerInterface represents all server handlers.
type ServerInterface interface {
	// List book sources.
	// (GET /book-sources)
	ListBookSources(w http.ResponseWriter, r *http.Request, params ListBookSourcesParams)
	// Create a book source.
	// (POST /book-sources)
	CreateBookSource(w http.ResponseWriter, r *http.Request)
	// Import Legado-compatible book source JSON.
	// (POST /book-sources/import)
	ImportBookSources(w http.ResponseWriter, r *http.Request)
	// Reorder book sources.
	// (PATCH /book-sources/reorder)
	ReorderBookSources(w http.ResponseWriter, r *http.Request)
	// Delete one book source.
	// (DELETE /book-sources/{sourceId})
	DeleteBookSource(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// Get one book source.
	// (GET /book-sources/{sourceId})
	GetBookSource(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// Update one book source.
	// (PUT /book-sources/{sourceId})
	UpdateBookSource(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// Enable or disable one book source for search.
	// (PATCH /book-sources/{sourceId}/enabled)
	UpdateBookSourceEnabled(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// Enable or disable one book source for discovery.
	// (PATCH /book-sources/{sourceId}/explore-enabled)
	UpdateBookSourceExploreEnabled(w http.ResponseWriter, r *http.Request, sourceId SourceId)
	// List bookshelf books.
	// (GET /books)
	ListBooks(w http.ResponseWriter, r *http.Request, params ListBooksParams)
	// Save a book to bookshelf.
	// (POST /books)
	CreateBook(w http.ResponseWriter, r *http.Request)
	// Delete a book.
	// (DELETE /books/{bookId})
	DeleteBook(w http.ResponseWriter, r *http.Request, bookId string)
	// Get a book by ID.
	// (GET /books/{bookId})
	GetBook(w http.ResponseWriter, r *http.Request, bookId string)
	// List chapter metadata for a book.
	// (GET /books/{bookId}/chapters)
	ListBookChapters(w http.ResponseWriter, r *http.Request, bookId string)
	// Get a chapter content.
	// (GET /books/{bookId}/chapters/{index}/content)
	GetBookChapterContent(w http.ResponseWriter, r *http.Request, bookId string, index int)
	// Save reading progress.
	// (PUT /books/{bookId}/progress)
	UpdateBookProgress(w http.ResponseWriter, r *http.Request, bookId string)
	// Refresh book information from source.
	// (POST /books/{bookId}/refresh-info)
	RefreshBookInfo(w http.ResponseWriter, r *http.Request, bookId string)
	// Refresh chapter list from source.
	// (POST /books/{bookId}/refresh-toc)
	RefreshBookToc(w http.ResponseWriter, r *http.Request, bookId string)
	// Start an asynchronous book source check task.
	// (POST /check/book-sources)
	CreateBookSourceCheckTask(w http.ResponseWriter, r *http.Request)
	// Cancel check task.
	// (DELETE /check/tasks/{taskId})
	CancelCheckTask(w http.ResponseWriter, r *http.Request, taskId string)
	// Get check task state.
	// (GET /check/tasks/{taskId})
	GetCheckTask(w http.ResponseWriter, r *http.Request, taskId string)
	// Stream check task events as server-sent events.
	// (GET /check/tasks/{taskId}/events)
	StreamCheckTaskEvents(w http.ResponseWriter, r *http.Request, taskId string)
	// Create a book source debug session.
	// (POST /debug/book-source)
	CreateDebugSession(w http.ResponseWriter, r *http.Request)
	// Cancel debug session.
	// (DELETE /debug/sessions/{sessionId})
	CancelDebugSession(w http.ResponseWriter, r *http.Request, sessionId string)
	// Get debug session state.
	// (GET /debug/sessions/{sessionId})
	GetDebugSession(w http.ResponseWriter, r *http.Request, sessionId string)
	// Stream debug session events as server-sent events.
	// (GET /debug/sessions/{sessionId}/events)
	StreamDebugSessionEvents(w http.ResponseWriter, r *http.Request, sessionId string)
	// Fetch discovery results from enabled discovery sources.
	// (POST /discovery)
	DiscoverBooks(w http.ResponseWriter, r *http.Request)
	// Check service health.
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// Proxy a cover or chapter image through the Reader fetcher.
	// (GET /images/proxy)
	ProxyImage(w http.ResponseWriter, r *http.Request, params ProxyImageParams)
	// Download the OpenAPI document.
	// (GET /openapi.yaml)
	GetOpenAPI(w http.ResponseWriter, r *http.Request)
	// List replace rules.
	// (GET /replace-rules)
	ListReplaceRules(w http.ResponseWriter, r *http.Request)
	// Create replace rule.
	// (POST /replace-rules)
	CreateReplaceRule(w http.ResponseWriter, r *http.Request)
	// Test a replace rule against text.
	// (POST /replace-rules/test)
	TestReplaceRule(w http.ResponseWriter, r *http.Request)
	// Delete replace rule.
	// (DELETE /replace-rules/{ruleId})
	DeleteReplaceRule(w http.ResponseWriter, r *http.Request, ruleId int64)
	// Update replace rule.
	// (PUT /replace-rules/{ruleId})
	UpdateReplaceRule(w http.ResponseWriter, r *http.Request, ruleId int64)
	// Search books across one or more enabled sources.
	// (POST /search)
	SearchBooks(w http.ResponseWriter, r *http.Request)
	// Get service version.
	// (GET /version)
	GetVersion(w http.ResponseWriter, r *http.Request)
}

